import type { FC, HTMLAttributes } from 'react';
import { cn } from '@/lib/utils';

interface SectionTitleProps extends HTMLAttributes<HTMLDivElement> {
  title: string;
  subtitle?: string;
  centered?: boolean;
}

const SectionTitle: FC<SectionTitleProps> = ({ title, subtitle, centered = false, className, ...props }) => {
  return (
    <div className={cn('mb-8 md:mb-12', centered ? 'text-center' : '', className)} {...props}>
      <h2 className="text-3xl md:text-4xl font-bold font-headline text-primary mb-2">
        {title}
      </h2>
      {subtitle && (
        <p className="text-lg md:text-xl text-muted-foreground max-w-3xl mx-auto">
          {subtitle}
        </p>
      )}
    </div>
  );
};

export default SectionTitle;
